using System;using System.IO;using System.Reflection;using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;
public static class AvatarContourRegression {
static BindingFlags f=BindingFlags.Instance|BindingFlags.NonPublic;static int count;
static void Set(object o,string n,object v)=>o.GetType().GetField(n,f).SetValue(o,v);
static void Check(bool yes,string why){if(!yes)throw new Exception(why);count++;}
static Image Img(string name,Transform parent){var o=new GameObject(name,typeof(RectTransform),typeof(CanvasRenderer),typeof(Image));o.transform.SetParent(parent,false);return o.GetComponent<Image>();}
public static void Run(){try{
var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var root=new GameObject("Avatar",typeof(RectTransform));var avatar=root.AddComponent<AvatarView>();Set(avatar,"atualizarNoEditor",false);var body=Img("Body",root.transform);var hat=Img("Hat",root.transform);var tex=new Texture2D(4,4);var sprite=Sprite.Create(tex,new Rect(0,0,4,4),Vector2.one*.5f);Set(avatar,"bodyImage",body);Set(avatar,"bodySprite",sprite);Set(avatar,"hatImage",hat);Set(avatar,"hatOptions",new Sprite[]{null,sprite});hat.gameObject.SetActive(false);
avatar.Apply(new AvatarCustomizationData{HatIndex=1});Check(hat.gameObject.activeSelf&&hat.enabled,"Equipped hat reactivates its GameObject");
Check(body.GetComponent<AvatarSpriteOutline>()==null,"Reproduce open scene missing outline");int repairs=AvatarContourHierarchyRepair.Synchronize(scene);Check(repairs>=2,"Editor repairs existing open scene");Check(body.GetComponent<AvatarSpriteOutline>()?.enabled==true,"Customization body outline exists and is enabled");Check(hat.GetComponent<AvatarSpriteOutline>()?.enabled==true,"Customization hat outline exists and is enabled");Check(body.GetComponent<AvatarSpriteOutline>().Thickness==10,"Large preview width preserved");Check(AvatarContourHierarchyRepair.Synchronize(scene)==0,"Repair is idempotent");
var target=Img("CardPortrait",null);var to=target.gameObject.AddComponent<AvatarSpriteOutline>();to.Thickness=3.5f;to.enabled=false;root.SetActive(false);var copy=typeof(ComboCrewWorkerView).GetMethod("CopyPortraitOutline",BindingFlags.NonPublic|BindingFlags.Static);copy.Invoke(null,new object[]{body,target});Check(to.enabled,"Inactive worker still supplies enabled outline to card");Check(to.Thickness==3.5f,"Card retains reduced outline width");
root.SetActive(true);Set(avatar,"fallbackHatIndex",1);var saved=new AvatarCustomizationData{HatIndex=0};hat.gameObject.SetActive(false);avatar.Apply(saved);Check(hat.gameObject.activeSelf&&hat.sprite!=null,"Combo Crew fallback hat is visible");Check(saved.HatIndex==0,"Fallback does not change saved customization");
body.GetComponent<AvatarSpriteOutline>().enabled=false;hat.GetComponent<AvatarSpriteOutline>().enabled=false;avatar.Apply(new AvatarCustomizationData{HatIndex=1});Check(body.GetComponent<AvatarSpriteOutline>().enabled&&hat.GetComponent<AvatarSpriteOutline>().enabled,"Applying avatar preserves both outlines");
File.WriteAllText(@"E:/SSD/GITHUB/MEQUI BREAK/tmp/avatar-contour-repair/regression-result.txt","PASS "+count+" targeted checks");EditorApplication.Exit(0);
}catch(Exception e){File.WriteAllText(@"E:/SSD/GITHUB/MEQUI BREAK/tmp/avatar-contour-repair/regression-result.txt",e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
}